  {
    "question": "According to the three‑schema architecture, a view that displays only the student’s name and ID for the registrar is an example of which level?",
    "options": {
      "A": "External level",
      "B": "Conceptual level",
      "C": "Internal level",
      "D": "Physical level"
    },
    "correct_answer": "A",
    "explanation": "A view that tailors data for a specific user (the registrar) is an external schema; it defines a user‑oriented representation of the data.",
    "difficulty": "Medium"
  },
  {
    "question": "Which relational‑algebra expression returns the names of all students enrolled in the course titled “DBMS”?",
    "options": {
      "A": "π_{student_name}(σ_{title='DBMS'}(Course) ⨝ Enrollment ⨝ Student)",
      "B": "σ_{title='DBMS'}(π_{student_name}(Student ⨝ Enrollment ⨝ Course))",
      "C": "π_{student_name}(Student) − π_{student_name}(σ_{title≠'DBMS'}(Course) ⨝ Enrollment)",
      "D": "ρ_{S}(Student) ⋈_{S.student_id=E.student_id} (σ_{title='DBMS'}(Course) ⋈_{E.course_id=C.course_id} Enrollment)"
    },
    "correct_answer": "A",
    "explanation": "First select the DBMS course, join with Enrollment to get matching student IDs, then join with Student and project the student_name attribute.",
    "difficulty": "Medium"
  },
  {
    "question": "A sudden power outage that leaves some disk pages only partially written is an example of which failure type?",
    "options": {
      "A": "Transaction failure",
      "B": "System failure",
      "C": "Media failure",
      "D": "Logical failure"
    },
    "correct_answer": "C",
    "explanation": "Media failures involve loss or corruption of the storage medium (e.g., disk) caused by events like power loss, requiring redo/undo recovery.",
    "difficulty": "Medium"
  },
  {
    "question": "In a precedence (conflict‑serializability) graph, if transaction T1 writes item X and later transaction T2 reads X, which directed edge is added?",
    "options": {
      "A": "T2 → T1",
      "B": "T1 → T2",
      "C": "Both T1 → T2 and T2 → T1",
      "D": "No edge, because read‑after‑write is not a conflict"
    },
    "correct_answer": "B",
    "explanation": "A write‑read conflict creates an edge from the writer (T1) to the reader (T2) indicating that T1 must precede T2 in any equivalent serial schedule.",
    "difficulty": "Medium"
  },
  {
    "question": "To list each course that has at least ten enrolled students, which clause must be used after the GROUP BY in the SQL query?",
    "options": {
      "A": "WHERE",
      "B": "HAVING",
      "C": "ORDER BY",
      "D": "LIMIT"
    },
    "correct_answer": "B",
    "explanation": "HAVING filters groups after aggregation; the condition COUNT(*) ≥ 10 belongs in HAVING, not WHERE.",
    "difficulty": "Medium"
  }
]
